"""dev.6 reference query for equivalence tests and synthetic benchmarks."""
BASELINE_SQL = 'SELECT ? || "/" || ((CAST(substr(d.cell,4,instr(substr(d.cell,4),\'/\')-1) AS INTEGER)) >> ?) || "/" || ((CAST(substr(d.cell,4+instr(substr(d.cell,4),\'/\')) AS INTEGER)) >> ?) AS cell,\n                    sum(observation_count) AS observation_count, sum(passage_count) AS passage_count,\n                    sum(below_1200_ft) AS below_1200_ft, sum("1200_to_17999_ft") AS "1200_to_17999_ft",\n                    sum("18000_ft_and_above") AS "18000_ft_and_above", sum(unknown) AS unknown,\n                    min(min_ft) AS min_ft, max(max_ft) AS max_ft,\n                    min(first_observed) AS first_observed, max(last_observed) AS last_observed,\n                    min(history_complete) AS history_complete\n                    FROM daily d JOIN cell_locations l ON l.cell=d.cell WHERE day BETWEEN ? AND ? AND l.x BETWEEN ? AND ? AND l.y BETWEEN ? AND ? GROUP BY (CAST(substr(d.cell,4,instr(substr(d.cell,4),\'/\')-1) AS INTEGER) >> ?), (CAST(substr(d.cell,4+instr(substr(d.cell,4),\'/\')) AS INTEGER) >> ?)'
